function loadSaved(){try{let v=JSON.parse(localStorage.getItem(SAVE_KEY)||'[]');return new Set(Array.isArray(v)?v.filter(id=>SLOTS.some(s=>s.id===id)):[])}catch{return new Set()}}
function loadWiring(){try{let v=JSON.parse(localStorage.getItem(SAVE_KEY+'-wires')||'[]');return new Set(Array.isArray(v)?v.filter(id=>WIRES.some(s=>s.id===id)):[])}catch{return new Set()}}
function store(){try{localStorage.setItem(SAVE_KEY,JSON.stringify([...installed]));localStorage.setItem(SAVE_KEY+'-wires',JSON.stringify([...wiring]));localStorage.setItem(SAVE_KEY+'-verified',String(verified));localStorage.setItem(SAVE_KEY+'-bec',becMode);localStorage.setItem(SAVE_KEY+'-battery',String(batteryVolts));localStorage.setItem(SAVE_KEY+'-load',String(loadAmps))}catch{}}
try{becMode='5';batteryVolts=11.1;loadAmps=0.8;verified=localStorage.getItem(SAVE_KEY+'-verified')==='true'}catch{}
const ASSEMBLY_ORDER=['frame','post','motor','esc','pdb','fc','rx','battery','strap'];
function stepNow(){for(let i=0;i<9;i++)if(SLOTS.some(s=>s.type===ASSEMBLY_ORDER[i]&&!installed.has(s.id)))return i;
 if(['fpvCam','fpvVtx','fpvAnt','gpsMount','gps'].some(t=>remaining(t)))return 9;
 if(wiring.size<WIRES.length)return 10;
 if(!verified)return 11;
 if(SLOTS.some(s=>s.type.startsWith('prop')&&!installed.has(s.id)))return 12;
 return 14;
}
function remaining(type){return SLOTS.filter(s=>s.type===type&&!installed.has(s.id)).length}
function partInfo(type){return PARTS.find(p=>p.type===type)}
function currentSuggested(){let s=stepNow();if(activeView==='piloto')return PILOT_TYPES.find(t=>remaining(t))||null;if(s===12)return remaining('propCW')?'propCW':(remaining('propCCW')?'propCCW':null);if(s===9)return ['fpvCam','fpvVtx','fpvAnt','gpsMount','gps'].find(t=>remaining(t))||null;if(s<=8)return ASSEMBLY_ORDER[s];return null}
function slotAllowed(slot,type){return !installed.has(slot.id)&&slot.type===type&&partInfo(type)?.step===stepNow()&&(!slot.needs||installed.has(slot.needs))}
function notify(msg,bad=false){const t=$('toast');t.textContent=msg;t.classList.toggle('bad',bad);t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),3400)}
function selectPart(type){
 const part=partInfo(type),s=stepNow();if(!part)return;
 if(PILOT_TYPES.includes(type)){
   if(activeView!=='piloto'){notify('Estos accesorios solo se colocan en la vista Piloto.',true);return}
   if(installed.has(type)){notify(`${part.name} ya está colocado en el piloto.`);return}
   const slot=SLOTS.find(x=>x.id===type);install(slot,type);return;
 }
 if(activeView==='piloto'){notify('Cambia a Dron para colocar esa pieza.',true);return}
 if(s===14){notify('¡Dron completo! Puedes probar los motores o reiniciar.');return}
 if(s===12&&part.step===12){const expected=currentSuggested();if(type!==expected){notify(`Primero instala las hélices ${expected==='propCW'?'CW':'CCW'} que corresponden a esta secuencia.`,true);return;}const next=SLOTS.find(slot=>slot.type===type&&!installed.has(slot.id)&&(!slot.needs||installed.has(slot.needs)));if(next){install(next,type);return;}notify('Todas las hélices de este tipo están instaladas.');return;}
 if(part.step!==s){notify(part.step>s?`Primero completa la etapa ${s+1}: ${STEPS[s].title.toLowerCase()}.`:'Esta pieza pertenece a una etapa completada.',true);return}
 if(!remaining(type)){notify(`Todas las unidades de ${part.name.toLowerCase()} están instaladas.`);return}
 selected=type;updateUI();if(window.matchMedia('(max-width:900px)').matches)viewport.scrollIntoView({behavior:'smooth',block:'center'});
 notify(`Seleccionaste ${part.name}. Toca su posición en el modelo 3D.`)
}
function install(slot,type=selected){
 if(slot&&PILOT_TYPES.includes(slot.type)){
   if(activeView!=='piloto'){notify('Cambia a Piloto para instalar este accesorio.',true);return}
   if(installed.has(slot.id)){notify('Este accesorio ya está instalado.');return}
   installed.add(slot.id);history.push(slot.id);store();selected=PILOT_TYPES.find(t=>!installed.has(t))||null;updateUI();
   if(PILOT_TYPES.every(t=>installed.has(t)))notify('✓ Piloto listo');
   else notify(`✓ ${slot.name} colocado. Selecciona el siguiente accesorio.`);return;
 }
 if(activeView==='piloto'){notify('El montaje del dron se realiza en la vista Dron.',true);return;}
 if(!type){notify('Selecciona una pieza del inventario.',true);return}if(!slotAllowed(slot,type)){if(slot.type!==type)notify(`Este lugar corresponde a ${slot.name}, no a ${partInfo(type)?.name||'esa pieza'}.`,true);else notify('Primero completa las etapas anteriores.',true);return}
 const prev=stepNow();installed.add(slot.id);history.push(slot.id);store();if(prev===12)selected=null;else if(remaining(type)===0)selected=currentSuggested();testActive=false;$('testControl').classList.remove('show');updateUI();notify(prev===12?`✓ Hélice ${slot.type==='propCW'?'CW (horaria)':'CCW (antihoraria)'} instalada con un clic en el motor ${slot.side}.`:`✓ ${slot.name} instalado correctamente (${slot.side}).`);
 if(stepNow()===14&&prev===12)setTimeout(()=>{if(stepNow()===14&&activeView==='dron')openModal()},450);
}
function undo(){if(activeView==='piloto'){const last=[...history].reverse().find(id=>PILOT_TYPES.includes(id)&&installed.has(id));if(!last){notify('No hay accesorios del piloto para retirar.');return}installed.delete(last);history=history.filter(id=>id!==last);selected=last;store();updateUI();notify('↶ Accesorio retirado del piloto.');return}
 if(stepNow()===14)closeModal();if(stepNow()>=10&&stepNow()<=12&&wiring.size&&installed.size>=21&&stepNow()<12){let id=wireHistory.pop();wiring.delete(id);verified=false;store();updateUI();notify('↶ Último cable retirado.');return}
 if(stepNow()>=12&&installed.size===21&&verified){verified=false;store();updateUI();notify('↶ Verificación eléctrica anulada.');return}
 if(!history.length){if(wireHistory.length){let id=wireHistory.pop();wiring.delete(id);verified=false;store();updateUI();notify('↶ Conexión deshecha.')}else notify('No hay más acciones para deshacer.');return}
 let last=[...history].reverse().find(id=>!PILOT_TYPES.includes(id)&&installed.has(id));if(!last){notify('No hay piezas del dron para retirar.');return}history=history.filter(id=>id!==last);installed.delete(last);if(!wiring.size)verified=false;store();testActive=false;selected=SLOTS.find(s=>s.id===last).type;updateUI();notify('↶ Pieza retirada. Puedes volver a instalarla.')}
function reset(){if(activeView==='piloto'){if(!PILOT_TYPES.some(t=>installed.has(t))){notify('El piloto ya está sin accesorios.');return}if(!confirm('¿Reiniciar solo el equipo del piloto? El dron no cambiará.'))return;PILOT_TYPES.forEach(t=>installed.delete(t));history=history.filter(x=>!PILOT_TYPES.includes(x));selected='pilotGoggles';store();updateUI();notify('Equipo del piloto reiniciado.');return}
 if(!installed.size&&!wiring.size){notify('El dron ya está vacío.');return}if(!confirm('¿Reiniciar solamente el dron y su cableado? El piloto conservará su equipo.'))return;[...installed].filter(id=>!PILOT_TYPES.includes(id)).forEach(id=>installed.delete(id));wiring.clear();history=history.filter(x=>PILOT_TYPES.includes(x));wireHistory=[];selected='frame';testActive=false;power=35;verified=false;becMode='5';batteryVolts=11.1;loadAmps=0.8;store();$('powerRange').value='35';$('testControl').classList.remove('show');$('flightIndicator').classList.remove('show');$('powerResult').textContent='';updateUI();notify('Construcción reiniciada. ¡Empieza por el chasis!')}
function doTest(){if(activeView==='piloto')setView('dron');if(stepNow()!==14||!verified){notify('Antes completa montaje, cableado, piloto y verificación eléctrica.',true);return}closeModal();testActive=!testActive;$('testControl').classList.toggle('show',testActive);$('flightIndicator').classList.toggle('show',testActive);$('testBtn').textContent=testActive?'■ Detener simulación':'▶ Simular motores';$('safetyNote').textContent=testActive?'Animación virtual solamente · NO es una prueba eléctrica real.':'La animación es ilustrativa; no calcula empuje ni estabilidad.';notify(testActive?'Motores virtuales activados; puedes ajustar la potencia visual.':'Simulación de motores detenida.')}
function openModal(){showModal=true;$('completion').classList.add('show')}
function closeModal(){showModal=false;$('completion').classList.remove('show')}
function wireConnect(){if(stepNow()!==10){notify('Completa primero el montaje de componentes.',true);return}
 let from=$('wireFrom').value,to=$('wireTo').value;if(!from||!to){notify('Selecciona un puerto de origen y uno de destino.',true);return}
 let found=WIRES.find(x=>x.from===from&&x.to===to);
 if(!found){notify('⛔ Conexión incorrecta. Comprueba los puertos, señales y polaridad.',true);$('wireFaults').textContent=String(Number($('wireFaults').textContent)+1);return}
 if(wiring.has(found.id)){notify('Ese cable ya está conectado.');return}
 wiring.add(found.id);wireHistory.push(found.id);verified=false;store();$('wireFrom').value='';$('wireTo').value='';updateUI();notify(`✓ Cable conectado: ${from} → ${to}.`)
}
function verifyPower(){if(stepNow()!==11){notify('Antes conecta todos los cables (sin hélices).',true);return}
 if(wiring.size<WIRES.length){notify('Completa primero las 25 conexiones del cableado.',true);$('powerResult').textContent='❌ Faltan conexiones por completar.';$('powerResult').dataset.state='bad';return}
 verified=true;selected=null;store();updateUI();$('powerResult').textContent='✓ Verificación educativa aprobada: ESC con VBAT y FC / RX con 5 V regulados.';$('powerResult').dataset.state='ok';notify('✓ Verificación aprobada. Haz clic sobre cada motor para colocar su hélice automáticamente.')
}

