 $('stepTip').textContent=pilot?'Las gafas analógicas necesitan alimentación compatible. La antena puede venir integrada en las gafas o en su receptor.':cfg.tip+(step===14?' El GPS de esta versión va montado en el dron como módulo externo.':'');
