 $('dots').innerHTML=Array.from({length:pilot?PILOT_TYPES.length:13},(_,i)=>`<span class="${i<(pilot?pilotCount:step)?'done':i===(pilot?pilotCount:step)?'current':''}"></span>`).join('');
