 $('canvasStatus').textContent=pilot?(pilotComplete?'Piloto listo':`Equipo del piloto: ${pilotCount} de ${PILOT_TYPES.length} accesorios.`):(step===14?`Dron completo: ${DRONE_PARTS_COUNT} piezas, ${WIRES.length} conexiones y BEC verificado.`:step===10?`Toca ORIGEN o DESTINO en el modelo para conectar: ${wiring.size} / ${WIRES.length}.`:step===11?'Revisa la advertencia y verifica el BEC de 5,0 V.':selected?`Seleccionada: ${partInfo(selected)?.name}. Toca su punto iluminado.`:'Sigue las indicaciones del panel lateral.');
 $('safetyNote').textContent=pilot?(pilotComplete?'Piloto listo.':'Los accesorios del piloto no cuentan como piezas del dron.'):(step===14?'Simulación visual; nunca pruebes motores reales con hélices instaladas.':`Completa las ${DRONE_TOTAL_TASKS} tareas del dron para desbloquear la simulación.`);
