 $('benchProgressFill').style.width=(pilot?pilotCount/PILOT_TYPES.length:droneCount/DRONE_PARTS_COUNT)*100+'%';
 if(lastBenchStep!==`${activeView}-${step}-${pilotCount}`){lastBenchStep=`${activeView}-${step}-${pilotCount}`;if(!pilot&&step===10){wireCursor=Math.max(0,WIRES.findIndex(w=>!wiring.has(w.id)));focusedWire=WIRES[wireCursor]?.id||null;wireFilter='all';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter==='all');b.setAttribute('aria-pressed',String(b.dataset.filter==='all'))})}requestAnimationFrame(()=>locateCurrentPart());}else requestAnimationFrame(syncBenchBar);
 updateWireStage(step);
 $('wiringPanel').hidden=pilot||step!==10;
 document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',!pilot&&(step===10?'wiring':step===11?'power':step===14?'flight':'assembly')===b.dataset.mode));
