 $('refDesc').textContent=ref.desc||'';
 const local=WIRE_ART_ASSETS[ref.art]||ART_ASSETS[ref.art]||ART_ASSETS.frame; const remote=FPV_LOADED_ASSETS[ref.art];
 const altPrefix=step===10?'Imagen ilustrativa del cable o esquema de conexión':'Imagen ilustrativa del componente';
 $('refPhoto').innerHTML=`<img src="${remote||local}" data-part-photo="${ref.art}" data-fallback="${local}" alt="${altPrefix}: ${ref.title}" loading="eager" onerror="this.onerror=null;this.src=this.dataset.fallback">`;
 $('refSpecs').innerHTML=(ref.specs||[]).map(t=>`<li>${t}</li>`).join('');
