const WIRE_DESCRIPTIONS={
 batPos:'Positivo (+) de batería a la entrada positiva de la PDB.',
 batNeg:'Negativo (−) de batería a la tierra de entrada PDB.',
 bec5:'5 V regulados desde el BEC a la entrada de 5 V de la FC.',
 fcGnd:'Tierra común del regulador a la FC (GND).',
 rx5:'5 V desde la salida de alimentación FC al receptor compatible.',
 rxGnd:'Tierra compartida FC ↔ receptor.',
 rxSignal:'Señal SBUS del receptor a entrada de señal compatible de la FC.',
 cam5:'Alimentación de cámara desde el BEC de 5 V (compatible con RunCam Phoenix 2).',
 camGnd:'Tierra compartida entre cámara y PDB.',
 vtxPower:'A02 requiere 7–35 V; VBAT de batería 3S (11,1 V nominales) es compatible con este ejemplo.',
 vtxGnd:'Tierra compartida de video y alimentación al VTX.',
 camVideo:'Video compuesto analógico: VIDEO OUT de la cámara hacia VIDEO IN del VTX.',
 vtxAnt:'Conexión coaxial de antena: A02 es MMCX; SpiroNet SMA/RP-SMA exige un adaptador apropiado. No conectar directamente. Nunca encender el VTX sin antena adecuada.'
};
function wireDetails(item){
 if(WIRE_DESCRIPTIONS[item.id])return WIRE_DESCRIPTIONS[item.id];
 if(item.kind==='power')return 'Lleva VBAT a la alimentación del ESC, sin reducir a 5 V.';
 if(item.kind==='ground')return 'Une la tierra GND del ESC con la PDB.';
 return 'Lleva la señal del motor del ESC al puerto correspondiente de la FC.';
}
function fullWireLabel(kind){return ({power:'ALIMENTACIÓN',ground:'TIERRA / GND',reg:'REGULACIÓN 5 V',signal:'SEÑAL',rf:'RF / COAXIAL'})[kind]||kind}
function updateWireStage(step){
 const note=$('wireStageMessage');
 if(step<10)note.innerHTML='<strong>Etapa de montaje:</strong> termina las 21 piezas de electrónica y estructura para activar las conexiones.';
 else if(step===10)note.innerHTML='<strong>Cableado:</strong> toca un punto dorado en el dron para conectar o usa el botón de la guía.';
 else note.innerHTML='<strong>Cableado terminado.</strong> Puedes revisar o retirar un cable para corregirlo.';
}
let wireCursor=0;
function renderWireTable(){
 const wr=WIRES[wireCursor]||WIRES[0];if(!wr)return;
 const n=wireCursor+1,done=wiring.has(wr.id);
 const colors={power:'#ff6579',ground:'#8fa3b5',reg:'#c9f371',signal:'#61cdec',rf:'#d8abff'};
 const types={power:'Alimentación positiva · VBAT',ground:'Tierra / GND',reg:'Alimentación regulada 5 V',signal:'Señal de control',rf:'Coaxial RF · MMCX a SMA/RP-SMA (adaptación requerida)'};
 const text=types[wr.kind];
 $('wireList').innerHTML=`<div class="one-wire">
 <div class="wire-number"><b>CONEXIÓN ${String(n).padStart(2,'0')}</b><span class="type" style="color:${colors[wr.kind]}">${fullWireLabel(wr.kind)}</span></div>
 <div class="wire-port"><small>ORIGEN</small><strong>${wr.from}</strong></div>
 <div class="wire-arrow">→</div>
 <div class="wire-port"><small>DESTINO</small><strong>${wr.to}</strong></div>
 <div class="wire-spec"><img class="wire-cable-photo" src="${wr.kind==='rf'?FPV_FALLBACK_ASSETS.fpvAnt:WIRE_ASSETS[wr.kind]}" alt="Render ilustrativo de cable ${text}"/><span>TIPO DE CABLE</span><strong style="font-size:10px;color:#e5faff">${text}</strong><i class="wire-swatch" style="background:${colors[wr.kind]}"></i></div>
 <div class="wire-main"><button data-wire="${wr.id}" class="${done?'done':''}">${done?'✓ Conectado · Quitar':'⚡ Conectar'}</button><button class="wire-3d" data-focuswire="${wr.id}">◎ Mostrar cable en 3D</button></div>
 </div>`;
 $('wirePrev').disabled=wireCursor===0;$('wireNextBtn').disabled=wireCursor===WIRES.length-1;
}
function advanceWire(next){
 wireCursor=Math.max(0,Math.min(WIRES.length-1,next));
 focusedWire=WIRES[wireCursor].id;renderWireTable();updateReferenceCard(10);
}
function connectOrDisconnectWire(wr){
 if(stepNow()<10){notify('Primero instala las 21 piezas anteriores al cableado.',true);return;}
 focusedWire=wr.id;
 if(wiring.has(wr.id)){
   wiring.delete(wr.id);wireHistory=wireHistory.filter(id=>id!==wr.id);verified=false;testActive=false;
   $('testControl').classList.remove('show');$('flightIndicator').classList.remove('show');
   notify(`Se retiró la conexión: ${wr.from} → ${wr.to}`);
 }else{
   wiring.add(wr.id);wireHistory.push(wr.id);verified=false;
   notify(`✓ Conectado: ${wr.from} → ${wr.to}`);
 }
 store();if(wiring.has(wr.id)){let n=WIRES.findIndex(w=>!wiring.has(w.id));if(n>=0)wireCursor=n;else wireCursor=Math.min(wireCursor+1,WIRES.length-1);focusedWire=WIRES[wireCursor]?.id||null;}updateUI();
}
function focusWire(wr){
 focusedWire=wr.id;
 if(wireFilter!=='all'&&wireFilter!==wr.kind){wireFilter='all';document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el.dataset.filter==='all');el.setAttribute('aria-pressed',String(el.dataset.filter==='all'))})}
 renderWireTable();

 camTarget.az=.49;camTarget.el=1.05;camTarget.dist=8.9;
 notify(`Cable destacado: ${wr.from} → ${wr.to}. Puedes girar el dron.`);
}
// Los dos puntos dorados son controles de conexión en la vista 3D.
function tryConnectCablePoint(x,y){
 if(activeView!=='dron'||stepNow()!==10)return false;
 const current=WIRES.find(w=>w.id===focusedWire)||WIRES[wireCursor];
 if(!current||!installed.has('pdb'))return false;
 const a=project(current.a),b=project(current.b);
 const radius=29;
 if(![a,b].some(p=>Math.hypot(p.x-x,p.y-y)<=radius))return false;
 connectOrDisconnectWire(current);
 return true;
}
function drawFocusedWire(){
 if(activeView!=='dron'||stepNow()!==10||!focusedWire||!installed.has('pdb'))return;
 const wr=WIRES.find(w=>w.id===focusedWire);if(!wr)return;
 const a=project(wr.a),b=project(wr.b),pulse=.7+.3*Math.sin(time*5);
 ctx.save();ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo((a.x+b.x)*.5,Math.min(a.y,b.y)-36,b.x,b.y);ctx.setLineDash([7,6]);ctx.strokeStyle=`rgba(255,212,117,${pulse})`;ctx.lineWidth=3.5;ctx.stroke();ctx.setLineDash([]);
 for(let [p,label] of [[a,'ORIGEN'],[b,'DESTINO']]){
 ctx.beginPath();ctx.arc(p.x,p.y,20+3*Math.sin(time*4),0,Math.PI*2);ctx.fillStyle='rgba(255,208,113,.12)';ctx.fill();ctx.strokeStyle='rgba(255,220,149,.66)';ctx.lineWidth=2;ctx.stroke();
 ctx.beginPath();ctx.arc(p.x,p.y,10,0,Math.PI*2);ctx.fillStyle='#ffd16e';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
 ctx.fillStyle='#081929';ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('+',p.x,p.y+0.3);
 ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.textBaseline='alphabetic';let x=clamp(p.x,45,w-45),y=clamp(p.y-28,15,h-22);
 ctx.fillStyle='#fff5cb';ctx.fillText(label,x,y);
 }ctx.restore();
}
/* --- Motor de dibujo de modelos 3D, proyección de cámara real, material y sombreado --- */
function resize(){let r=viewport.getBoundingClientRect();w=Math.max(10,r.width);h=Math.max(10,r.height);dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
function updateCamera(){camera.az=lerp(camera.az,camTarget.az,.2);camera.el=lerp(camera.el,camTarget.el,.2);camera.dist=lerp(camera.dist,camTarget.dist,.2);
 eye=norm([Math.sin(camera.az)*Math.cos(camera.el),Math.sin(camera.el),Math.cos(camera.az)*Math.cos(camera.el)]);right=norm(cross([0,1,0],eye));up=norm(cross(eye,right));}
function project(p){let r=sub(p,[0,.37,0]),depth=camera.dist-dot(r,eye);let focal=Math.min(w,h)*1.53;let scale=focal/Math.max(.15,depth);return {x:w*.5+dot(r,right)*scale,y:h*.555-dot(r,up)*scale,s:scale,depth}}
function poly(points,color,edge=null,opacity=1){if(points.length<3)return;let normal=norm(cross(sub(points[1],points[0]),sub(points[2],points[0])));let light=norm([-.4,1.3,.6]);let bright=clamp(.60+Math.abs(dot(normal,light))*.38,.4,1.05);let depth=dot(points.reduce((a,p)=>add(a,p),[0,0,0]).map(v=>v/points.length),eye);faces.push({points,color,edge,opacity,depth,bright})}
function transform(v,pos,ry=0){let c=Math.cos(ry),s=Math.sin(ry);return [pos[0]+c*v[0]+s*v[2],pos[1]+v[1],pos[2]-s*v[0]+c*v[2]]}
function box(pos,size,color,ry=0,edge=null,opacity=1){let [sx,sy,sz]=size.map(v=>v/2);let v=[[-sx,-sy,-sz],[sx,-sy,-sz],[sx,sy,-sz],[-sx,sy,-sz],[-sx,-sy,sz],[sx,-sy,sz],[sx,sy,sz],[-sx,sy,sz]].map(q=>transform(q,pos,ry));for(let ix of [[0,1,2,3],[5,4,7,6],[4,0,3,7],[1,5,6,2],[3,2,6,7],[4,5,1,0]])poly(ix.map(i=>v[i]),color,edge,opacity)}
function cylinder(pos,r,thickness,color,n=13,edge=null,opacity=1){const b=[],t=[];for(let i=0;i<n;i++){let angle=i*Math.PI*2/n,bx=pos[0]+Math.cos(angle)*r,bz=pos[2]+Math.sin(angle)*r;b.push([bx,pos[1]-thickness/2,bz]);t.push([bx,pos[1]+thickness/2,bz])}poly([...t],color,edge,opacity);poly([...b].reverse(),color,edge,opacity);for(let i=0;i<n;i++){let j=(i+1)%n;poly([b[i],b[j],t[j],t[i]],color,edge,opacity)}}
function diskOutline(pos,r,color='#47b5cc',weight=1.5,alpha=1){let points=[];for(let i=0;i<=32;i++){let a=i*Math.PI*2/32;points.push([pos[0]+r*Math.cos(a),pos[1],pos[2]+r*Math.sin(a)])}segments.push({points,color,weight,alpha})}
function path3d(points,color,weight=2,alpha=1){segments.push({points,color,weight,alpha})}
function makeFrame(ghost=false){let op=ghost?.2:1;for(let [x,z] of [[-2,-2],[2,-2],[-2,2],[2,2]]){let ry=-Math.atan2(z,x),len=Math.hypot(x,z);box([x*.5,.25,z*.5],[len,.19,.34],ghost?'#698397':'#242c3a',ry,'#678aa1',op);box([x*.5,.36,z*.5],[len-.08,.045,.18],ghost?'#607d91':'#101827',ry,null,op);cylinder([x,.29,z],.39,.12,ghost?'#496b81':'#263d52',12,'#6e9bae',op)}
 box([0,.26,0],[1.55,.22,1.35],ghost?'#567b93':'#1d2535',0,'#58798d',op);box([0,.40,0],[1.37,.09,1.15],ghost?'#5d879b':'#2b3b49',0,'#8ab5c6',op);if(!ghost){for(let [x,z] of [[-.60,-.46],[.60,-.46],[-.60,.46],[.60,.46]]){cylinder([x,.474,z],.065,.045,'#afc3d1',9)}box([0,.11,0],[.75,.14,1.05],'#1b2d3a');}}
function makeMotor(s){let [x,,z]=s.p;cylinder([x,.45,z],.33,.33,'#375267',15,'#779aab');cylinder([x,.64,z],.29,.18,'#c78542',15);cylinder([x,.75,z],.22,.045,'#a55a27',14);cylinder([x,.79,z],.09,.10,'#c4d9e0',13);for(let a=0;a<12;a++){let theta=a*Math.PI/6;cylinder([x+.269*Math.cos(theta),.56,z+.269*Math.sin(theta)],.035,.10,'#e28a40',6)}}
function makeEsc(s){let [x,,z]=s.p,ry=-Math.atan2(z,x);box([x,.45,z],[.65,.14,.4],'#253b40',ry,'#438e83');box([x,.54,z],[.45,.035,.27],'#133f3f',ry,'#61b9a5');box([x,.565,z],[.19,.025,.16],'#28303b',ry);for(let i=-1;i<=1;i++)box([x+i*.13,.555,z+.18],[.04,.025,.065],'#c3b67d',ry)}
function makeFC(){box([0,.81,-.38],[1.09,.09,.96],'#1f514b',0,'#74bca1');box([0,.88,-.38],[.5,.075,.45],'#273f49',0,'#648c9d');box([0,.93,-.37],[.23,.034,.19],'#111e2c');for(let x of [-.38,-.22,.22,.38])for(let z of [-.80,-.20])box([x,.88,z+.12],[.045,.022,.085],'#d4af62');box([0,.88,-.69],[.30,.025,.055],'#68eab4');path3d([[0,.94,-.72],[0,.94,-.54]],'#75f3dc',3)}
function makeBattery(){box([0,.91,.85],[1.48,.43,.84],'#244fbe',0,'#687b91');box([0,1.14,.85],[1.31,.05,.78],'#4785ea',0,'#ffcf80');box([0,1.18,.85],[.6,.027,.35],'#295cc7');box([-.49,1.14,.85],[.19,.04,.70],'#f8ca83');box([.49,1.14,.85],[.19,.04,.70],'#f8ca83');path3d([[.62,1.03,.85],[.84,.90,.66],[1.0,.72,.42]],'#f27173',3);path3d([[.62,.97,.81],[.85,.84,.6],[1.06,.68,.44]],'#1c1e24',3)}
function makePost(s){let [x,,z]=s.p;cylinder([x,.55,z],.073,.36,'#bfcaac',9,'#ddf3d9');cylinder([x,.76,z],.115,.045,'#829bab',10)}
function makePdb(){box([0,.55,.06],[1.35,.115,1.10],'#16444c',0,'#71e1d5');box([0,.62,.06],[.39,.075,.31],'#16363d',0,'#57aeb4');box([-.28,.63,.08],[.20,.06,.24],'#c69b67',0,'#ecc38c');
 for(let x of [-.49,.49])for(let z of [-.31,.35]){box([x,.617,z],[.16,.028,.13],'#e0a76e');box([x*.91,.625,z*.8],[.07,.033,.062],'#dd4e55')}
 box([0,.64,.49],[.52,.035,.10],'#53ce9e');box([0,.65,-.42],[.42,.025,.075],'#e0bd68');
}
function makeRx(){box([.25,.79,-1.14],[.55,.16,.33],'#2b6275',0,'#7fdde4');box([.25,.88,-1.14],[.26,.032,.15],'#193044');path3d([[.12,.84,-1.25],[-.18,1.16,-1.63],[-.53,1.43,-1.81]],'#b8e3dc',2);path3d([[.38,.84,-1.25],[.61,1.15,-1.60],[.78,1.35,-1.95]],'#b8e3dc',2)}
function makeFpvCam(){
 box([0,.74,-1.66],[.55,.44,.52],'#252f3e',0,'#8795a6');
 box([0,.75,-1.97],[.41,.34,.09],'#131b27',0,'#7e94a2');
 const p=[];for(let i=0;i<20;i++){let a=2*Math.PI*i/20;p.push([.75*.24*Math.cos(a),.76+.24*Math.sin(a),-2.02]);}
 poly(p,'#284759','#9cc8e7');
 path3d([[.12,.75,-1.57],[.24,.80,-1.1]],'#e7bb60',2.2);
}
function makeFpvVtx(){
 box([.65,.77,1.55],[.67,.12,.59],'#174e54',0,'#74b9bb');
 box([.65,.845,1.54],[.29,.075,.23],'#1b2331',0,'#768ca2');
 for(let x of [.41,.90])for(let z of [1.33,1.75])cylinder([x,.85,z],.055,.025,'#e0bd6b',8);
 path3d([[.82,.86,1.71],[.84,1.02,1.78]],'#a6cbd4',2);
}
function makeFpvAnt(){
 cylinder([.82,1.21,1.72],.07,.52,'#bf665a',10);
 cylinder([.82,1.56,1.72],.21,.22,'#364958',15,'#83b2c4');
 cylinder([.82,1.69,1.72],.18,.025,'#7795a2',15);
}
function makeStrap(){box([0,1.22,.85],[.25,.085,1.0],'#c7db5d',0,'#eaff9f');box([0,1.24,.85],[.38,.027,.37],'#3b5351')}

function makeGpsMount(){
 box([0,1.14,-.08],[.26,.18,.26],'#263644',0,'#7da4b7');
 cylinder([0,1.38,-.09],.07,.45,'#445768',10,'#a8c6d7');
 box([0,1.60,-.10],[.85,.08,.44],'#3f5668',0,'#a9d8ea');
 box([0,1.64,-.10],[.45,.03,.18],'#1a2a38');
}
function makeGps(){
 cylinder([0,1.79,-.10],.42,.12,'#263542',18,'#88b5c7');
 cylinder([0,1.86,-.10],.35,.06,'#121c26',18,'#b2e6f2');
 box([0,1.89,-.10],[.46,.08,.16],'#203041',0,'#a8e7ef');
 path3d([[0,1.96,-.10],[0,2.10,-.10]],'#f6f9fb',2.3);
 path3d([[-.10,1.86,-.10],[-.10,1.73,-.10],[-.08,1.15,-.06]],'#baf567',1.9);
 path3d([[-.03,1.84,-.10],[-.03,1.72,-.10],[-.02,1.13,-.02]],'#73889a',1.8);
 path3d([[.05,1.84,-.10],[.05,1.72,-.10],[.06,1.14,-.02]],'#6fd7ef',1.8);
 path3d([[.12,1.82,-.10],[.12,1.70,-.10],[.11,1.15,-.06]],'#79d7ef',1.8);
}

function makeProp(s,angle){let [x,,z]=s.p,color=s.type==='propCW'?'#ffb878':'#6af2ed',bladeColor=s.type==='propCW'?'#e0905f':'#5abfc6';cylinder([x,.94,z],.18,.16,'#344d61',14);cylinder([x,1.045,z],.115,.07,color,12);
 // hélice realista estilizada: cada aspa es una lámina ancha que se afina en la punta
 for(let i=0;i<2;i++){let theta=angle+i*Math.PI,c=Math.cos(theta),sn=Math.sin(theta),w1=.16,w2=.135;let points=[[.07,-w1],[.50,-.24],[1.23,-w2],[1.52,-.028],[1.52,.06],[1.2,w2],[.48,.20],[.07,w1]].map(([radius,perp])=>[x+radius*c-perp*sn,1.055+(radius>1?.035:0),z+radius*sn+perp*c]);poly(points,bladeColor,color);poly(points.map(p=>[p[0],p[1]+.018,p[2]]),color,null,.92)}
}
function addWiring(){if(!installed.has('frame'))return;
 for(let s of SLOTS.filter(s=>s.type==='esc'&&installed.has(s.id))){let key=s.id.slice(3),m=SLOTS.find(p=>p.id==='motor'+key);if(m&&installed.has(m.id)){let [x,,z]=s.p;path3d([[x*.90,.53,z*.90],[x*1.29,.53,z*1.29],[m.p[0]*.88,.57,m.p[2]*.88]],'#e9af76',1.6)}}
 for(const wr of WIRES){if(!wiring.has(wr.id))continue;let a=wr.a,b=wr.b,color=wr.kind==='power'?'#ff737d':wr.kind==='ground'?'#718899':wr.kind==='reg'?'#c5f879':wr.kind==='rf'?'#cf9bff':'#76dbef';
 let hump=Math.max(a[1],b[1])+.18;path3d([a,[a[0],hump,a[2]],[lerp(a[0],b[0],.5),hump,lerp(a[2],b[2],.5)],[b[0],hump,b[2]],b],color,wr.kind==='power'?3.0:2.3);}
}
function model(){let frame=installed.has('frame');if(!frame)makeFrame(true);else makeFrame();for(let s of SLOTS){if(!installed.has(s.id))continue;if(s.type==='post')makePost(s);else if(s.type==='motor')makeMotor(s);else if(s.type==='esc')makeEsc(s);else if(s.type==='pdb')makePdb();else if(s.type==='fc')makeFC();else if(s.type==='rx')makeRx();else if(s.type==='battery')makeBattery();else if(s.type==='strap')makeStrap();else if(s.type==='fpvCam')makeFpvCam();else if(s.type==='fpvVtx')makeFpvVtx();else if(s.type==='fpvAnt')makeFpvAnt();else if(s.type==='gpsMount')makeGpsMount();else if(s.type==='gps')makeGps()}
 addWiring();for(let s of SLOTS){if(!installed.has(s.id)||!s.type.startsWith('prop'))continue;let dir=s.type==='propCW'?1:-1;makeProp(s,spin*dir+(s.type==='propCW'?.4:-.35))}
}
function rgb(str){let x=str.replace('#','');if(x.length===3)x=x.split('').map(ch=>ch+ch).join('');let n=parseInt(x,16)||0;return [(n>>16)&255,(n>>8)&255,n&255]}
function fillColor(hex,brightness=1,alpha=1){let [r,g,b]=rgb(hex);return `rgba(${clamp(Math.round(r*brightness),0,255)},${clamp(Math.round(g*brightness),0,255)},${clamp(Math.round(b*brightness),0,255)},${alpha})`}
function drawScene(){ctx.fillStyle='#101d2e';ctx.fillRect(0,0,w,h);let bg=ctx.createRadialGradient(w*.49,h*.54,10,w*.5,h*.50,Math.max(w,h)*.67);bg.addColorStop(0,'#254662');bg.addColorStop(.54,'#15283e');bg.addColorStop(1,'#0b1424');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
 // suelo 3D cuadriculado: perspectiva genuina y referencia de profundidad
 let floorY=-.64;for(let t=-9;t<=9;t++){let a=project([-9,floorY,t]),b=project([9,floorY,t]);let c=project([t,floorY,-9]),d=project([t,floorY,9]);drawLine(a,b,'#4a6d83',t===0?.23:.095,1);drawLine(c,d,'#4a6d83',t===0?.23:.095,1)}
 // sombra suave del dron sobre la mesa
 let shadowCenter=project([0,-.58,0]),radius=project([3.4,-.58,0]);let g=ctx.createRadialGradient(shadowCenter.x,shadowCenter.y,5,shadowCenter.x,shadowCenter.y,Math.max(130,Math.abs(radius.x-shadowCenter.x)*1.8));g.addColorStop(0,'#00000077');g.addColorStop(1,'#00000000');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(shadowCenter.x,shadowCenter.y,Math.min(w*.55,320),Math.min(h*.34,135),0,0,2*Math.PI);ctx.fill();
 // anillos en el suelo indican orientación y escala
 ring([0,-.60,0],3.65,'#426d81',.29);ring([0,-.59,0],2.55,'#34566e',.16);
 faces=[];segments=[];model();faces.sort((a,b)=>a.depth-b.depth);
 for(let face of faces){let p=face.points.map(project);ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);for(let i=1;i<p.length;i++)ctx.lineTo(p[i].x,p[i].y);ctx.closePath();ctx.fillStyle=fillColor(face.color,face.bright,face.opacity);ctx.fill();if(face.edge&&face.opacity>.6){ctx.strokeStyle=fillColor(face.edge,face.bright,.46);ctx.lineWidth=.65;ctx.stroke()}}
 for(let l of segments){if(l.points.length<2)continue;ctx.beginPath();let p=project(l.points[0]);ctx.moveTo(p.x,p.y);for(let i=1;i<l.points.length;i++){p=project(l.points[i]);ctx.lineTo(p.x,p.y)}ctx.strokeStyle=fillColor(l.color,1,l.alpha);ctx.lineWidth=l.weight;ctx.stroke()}
 drawTargets();drawPdbLabels();drawOrientation();drawFocusedWire();}
function drawLine(a,b,color,alpha=1,width=1){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=fillColor(color,1,alpha);ctx.lineWidth=width;ctx.stroke()}
function ring(center,r,color,alpha){let pre=null;for(let i=0;i<=96;i++){let theta=i*Math.PI*2/96,now=project([center[0]+r*Math.cos(theta),center[1],center[2]+r*Math.sin(theta)]);if(pre)drawLine(pre,now,color,alpha,1);pre=now}}
function rounded(x,y,width,height,radius=7){ctx.beginPath();ctx.roundRect(x,y,width,height,radius)}
function drawTargets(){targets=[];let step=stepNow();if(step>=10&&step!==12)return;let eligible=SLOTS.filter(s=>!installed.has(s.id)&&partInfo(s.type)?.step===step&&(!s.needs||installed.has(s.needs)));if(step===12){const expected=currentSuggested();eligible=eligible.filter(s=>s.type===expected);}
 for(let s of eligible){let p=project(s.p);targets.push({slot:s,x:p.x,y:p.y,r:Math.max(20,Math.min(30,p.s*.3))});let matched=step===12||selected===s.type;let pulse=.5+.5*Math.sin(time*3.4+(s.p[0]+s.p[2])*.5),radius=16+6*pulse;
 // objetivos tienen halo visible aunque la pieza no esté seleccionada, pero se destacan los coincidentes
 if(!hints&&!matched&&step!==12)continue;
 ctx.save();ctx.shadowBlur=matched?24:10;ctx.shadowColor=matched?'#68f8ec':'#ffc38a';ctx.beginPath();ctx.arc(p.x,p.y,radius+5,0,Math.PI*2);ctx.strokeStyle=matched?'#a0fff0':'#e0aa86';ctx.lineWidth=matched?2.3:1.4;ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(p.x,p.y,matched?7:4.5,0,Math.PI*2);ctx.fillStyle=matched?'#bcffae':'#ffd0aa';ctx.fill();ctx.restore();
 let label=s.name;ctx.font='bold 10px system-ui';let bw=Math.max(46,ctx.measureText(label).width+19);let bx=clamp(p.x-bw/2,8,w-bw-8),by=clamp(p.y-42,12,h-31);rounded(bx,by,bw,22,6);ctx.fillStyle=matched?'#234e57e8':'#493d37de';ctx.fill();ctx.strokeStyle=matched?'#65d9ce':'#c08b67';ctx.lineWidth=.8;ctx.stroke();ctx.textAlign='center';ctx.fillStyle=matched?'#c1ffff':'#ffdbb7';ctx.fillText(label,bx+bw/2,by+15)
 }
}
function drawPdbLabels(){if(!installed.has('pdb')||stepNow()<4||stepNow()>11)return;let p=project([0,.62,.06]);let label='PDB  ·  VBAT → ESC';let second='BEC 5 V → FC / RX';let bw=154,bh=42,xx=clamp(p.x+50,12,w-bw-12),yy=clamp(p.y+38,60,h-bh-10);
 ctx.beginPath();ctx.moveTo(p.x+4,p.y+4);ctx.lineTo(xx,yy+8);ctx.strokeStyle='#6bdedb';ctx.lineWidth=1.3;ctx.stroke();rounded(xx,yy,bw,bh,7);ctx.fillStyle='#103a44ed';ctx.fill();ctx.strokeStyle='#5fc9bc';ctx.stroke();ctx.textAlign='left';ctx.fillStyle='#bff7f0';ctx.font='bold 10px system-ui';ctx.fillText(label,xx+9,yy+16);ctx.fillStyle='#cafaa5';ctx.font='bold 10px system-ui';ctx.fillText(second,xx+9,yy+31)
}
function drawOrientation(){let o=project([0,.55,-3.65]);ctx.textAlign='center';ctx.font='900 10px system-ui';ctx.fillStyle='#e5aa82';ctx.fillText('▲ NARIZ / FRENTE',o.x,clamp(o.y,65,h-22));}
function loop(ts){let dt=Math.min(.05,Math.max(0,(ts-(loop.last||ts))/1000));loop.last=ts;time+=dt;if(testActive)spin+=dt*(2+power*.22);updateCamera();drawScene();requestAnimationFrame(loop)}
/* --- Cámara, punteros y colocación arrastrando --- */
function coords(event){const r=viewport.getBoundingClientRect();return{x:event.clientX-r.left,y:event.clientY-r.top}}
function nearest(x,y,type,limit=58){let matches=targets.filter(t=>!type||t.slot.type===type);matches.sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y));let t=matches[0];return t&&Math.hypot(t.x-x,t.y-y)<limit?t:null}
function wheel(e){if(activeView==='piloto')return;e.preventDefault();camTarget.dist=clamp(camTarget.dist+Math.sign(e.deltaY)*.65,6,20)}
const activePointers=new Map();let gestureDist=0;
viewport.addEventListener('pointerdown',e=>{if(activeView==='piloto')return;if(e.button!==0&&e.pointerType==='mouse')return;viewport.setPointerCapture(e.pointerId);activePointers.set(e.pointerId,coords(e));if(activePointers.size===1){let p=coords(e);dragCam={x:p.x,y:p.y,startX:p.x,startY:p.y,moved:false};}else dragCam=null;});
viewport.addEventListener('pointermove',e=>{if(activeView==='piloto')return;if(!activePointers.has(e.pointerId))return;let prev=activePointers.get(e.pointerId),cur=coords(e);activePointers.set(e.pointerId,cur);if(activePointers.size===2){let pts=[...activePointers.values()],pd=Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y);if(gestureDist)camTarget.dist=clamp(camTarget.dist+(gestureDist-pd)*.03,6,20);gestureDist=pd;return}if(!dragCam)return;let dx=cur.x-prev.x,dy=cur.y-prev.y;if(Math.hypot(cur.x-dragCam.startX,cur.y-dragCam.startY)>6)dragCam.moved=true;if(dragCam.moved){camTarget.az+=dx*.009;camTarget.el=clamp(camTarget.el+dy*.006,.17,1.48)}});
viewport.addEventListener('pointermove',e=>{if(activeView==='dron'&&stepNow()===12){const p=coords(e);viewport.style.cursor=nearest(p.x,p.y,null,68)?'pointer':'grab';return;}if(activeView!=='dron'||stepNow()!==10||!focusedWire)return;const wr=WIRES.find(w=>w.id===focusedWire);if(!wr)return;const p=coords(e);const pts=[project(wr.a),project(wr.b)];viewport.style.cursor=pts.some(q=>Math.hypot(q.x-p.x,q.y-p.y)<30)?'pointer':'grab';},{passive:true});
viewport.addEventListener('pointerup',e=>{if(activeView==='piloto')return;let p=coords(e);activePointers.delete(e.pointerId);gestureDist=0;if(dragCam&&!dragCam.moved){if(tryConnectCablePoint(p.x,p.y)){dragCam=null;return}const propStep=stepNow()===12;let expected=propStep?currentSuggested():null;let t=nearest(p.x,p.y,expected,propStep?68:38);if(t)install(t.slot,propStep?expected:selected);else if(propStep)notify(`Sigue la secuencia: instala ahora las hélices ${expected==='propCW'?'CW':'CCW'}.`,true);else if(selected&&stepNow()===0&&p.x>0)notify('Toca el círculo de montaje iluminado en el centro del modelo.')}if(activePointers.size===0)dragCam=null});
viewport.addEventListener('pointercancel',e=>{activePointers.delete(e.pointerId);dragCam=null;gestureDist=0});viewport.addEventListener('wheel',wheel,{passive:false});viewport.addEventListener('contextmenu',e=>e.preventDefault());
$('parts').addEventListener('click',e=>{let btn=e.target.closest('[data-part]');if(btn)selectPart(btn.dataset.part)});
$('partsWindow').addEventListener('scroll',syncBenchBar,{passive:true});
$('partsSlider').addEventListener('input',e=>{$('partsWindow').scrollLeft=Number(e.target.value);syncBenchBar()});
for(const [id,direction] of [['partsPrev',-1],['partsNext',1]]){$(id).addEventListener('click',()=>{let card=$('parts').querySelector('.part');let distance=(card?.getBoundingClientRect().width||175)+11;$('partsWindow').scrollBy({left:direction*distance*2,behavior:'smooth'});});}
$('showCurrentPart').addEventListener('click',locateCurrentPart);
window.addEventListener('resize',syncBenchBar);

$('parts').addEventListener('pointerdown',e=>{const btn=e.target.closest('[data-part]');if(!btn||btn.disabled||e.button!==0)return;dragPart={type:btn.dataset.part,x:e.clientX,y:e.clientY,moved:false,pointerId:e.pointerId};});
document.addEventListener('pointermove',e=>{if(!dragPart||dragPart.pointerId!==e.pointerId)return;if(Math.hypot(e.clientX-dragPart.x,e.clientY-dragPart.y)>11)dragPart.moved=true;if(dragPart.moved){let ghost=$('dragLabel');ghost.classList.add('show');ghost.textContent='✥ '+(partInfo(dragPart.type)?.name||'Pieza');ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';}});
document.addEventListener('pointerup',e=>{if(!dragPart||dragPart.pointerId!==e.pointerId)return;let info=dragPart;dragPart=null;$('dragLabel').classList.remove('show');if(!info.moved)return;let rect=viewport.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom){notify('Suelta la pieza dentro del área del modelo 3D.',true);return}if(PILOT_TYPES.includes(info.type)){selectPart(info.type);return}if(partInfo(info.type)?.step!==stepNow()){notify('Esa pieza corresponde a otra etapa del montaje.',true);return}selected=info.type;let p={x:e.clientX-rect.left,y:e.clientY-rect.top};let target=nearest(p.x,p.y,info.type,120);
 // Soltar dentro del visor también permite fijación asistida al punto correcto más cercano.
 if(!target){let all=targets.filter(t=>t.slot.type===info.type);all.sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));target=all[0]||null}
 if(target)install(target.slot,info.type);else notify('No hay una posición disponible para esa pieza.',true)
});
$('resetCamBtn').addEventListener('click',()=>{camTarget={az:.52,el:.83,dist:9.8};notify('Cámara restablecida')});
$('topBtn').addEventListener('click',()=>{camTarget.az=0;camTarget.el=1.47;camTarget.dist=10;notify('Vista superior activada')});
$('hintBtn').addEventListener('click',()=>{hints=!hints;$('hintBtn').classList.toggle('active',hints);$('hintBtn').setAttribute('aria-pressed',String(hints));notify(hints?'Pistas de montaje activadas.':'Pistas ocultas; la pieza seleccionada sigue iluminada.')});
$('undoBtn').addEventListener('click',undo);$('resetBtn').addEventListener('click',reset);$('testBtn').addEventListener('click',doTest);$('modalTestBtn').addEventListener('click',()=>{testActive=false;doTest()});$('closeModalBtn').addEventListener('click',closeModal);
$('completion').addEventListener('click',e=>{if(e.target===$('completion'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='ArrowLeft')camTarget.az-=.15;if(e.key==='ArrowRight')camTarget.az+=.15;if(e.key==='ArrowUp')camTarget.el=clamp(camTarget.el+.1,.17,1.48);if(e.key==='ArrowDown')camTarget.el=clamp(camTarget.el-.1,.17,1.48)});
$('wireList').addEventListener('click',e=>{
 const focusBtn=e.target.closest('button[data-focuswire]');
 if(focusBtn){const wr=WIRES.find(w=>w.id===focusBtn.dataset.focuswire);if(wr)focusWire(wr);return;}
 const btn=e.target.closest('button[data-wire]');if(!btn)return;
 const id=btn.dataset.wire,wr=WIRES.find(w=>w.id===id);if(!wr)return;
 connectOrDisconnectWire(wr);
});
for(const filter of document.querySelectorAll('[data-filter]'))filter.addEventListener('click',()=>{
 wireFilter=filter.dataset.filter;
 document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el.dataset.filter===wireFilter);el.setAttribute('aria-pressed',String(el.dataset.filter===wireFilter))});
 renderWireTable();
});
$('focusNextWire').addEventListener('click',()=>{
 const next=WIRES.find(w=>!wiring.has(w.id))||WIRES[0];focusWire(next);
});
$('becMode').addEventListener('change',()=>{});
$('batteryVolts').addEventListener('input',()=>{});
$('verifyBtn').addEventListener('click',verifyPower);
$('loadAmps').addEventListener('input',()=>{});
$('powerRange').addEventListener('input',e=>{power=Number(e.target.value);$('powerText').textContent=power+'%'});
window.addEventListener('resize',resize);if('ResizeObserver'in window)new ResizeObserver(resize).observe(viewport);
selected=currentSuggested();$('hintBtn').classList.add('active');updateUI();resize();requestAnimationFrame(loop);

// V4: navegación entre la conexión activa y las secciones habilitadas
$('wirePrev').addEventListener('click',()=>advanceWire(wireCursor-1));
$('wireNextBtn').addEventListener('click',()=>advanceWire(wireCursor+1));
for(const b of document.querySelectorAll('[data-mode]'))b.addEventListener('click',()=>{
 const mode=b.dataset.mode,step=stepNow();
 document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));
 if(mode==='assembly'){$('viewport').scrollIntoView({behavior:'smooth',block:'nearest'});notify('Mesa de montaje activa.');}
 if(mode==='wiring'){if(step===10){$('wiringPanel').scrollIntoView({behavior:'smooth',block:'nearest'});notify('Conecta los cables uno a uno.');}else notify(step<10?'Completa las 21 piezas para desbloquear el cableado.':'Cableado completado.');}
 if(mode==='power'){notify(step===11?'Configura y verifica el regulador BEC 5 V a la derecha.':'La configuración de energía se habilita después de las 25 conexiones.');}
 if(mode==='flight'){if(step===14)doTest();else notify('Completa las piezas, el cableado y la verificación del dron. El piloto es independiente.');}
});

for(const b of document.querySelectorAll('[data-scene-view]'))b.addEventListener('click',()=>setView(b.dataset.sceneView));
for(const btn of document.querySelectorAll('[data-pilot-slot]'))btn.addEventListener('click',()=>selectPart(btn.dataset.pilotSlot));

refreshPilotView();
